import{_ as a,o as s,c as i,al as t}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"Adding Standard MAVLink Definitions (Messages/Commands)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/mavlink/adding_messages.md","filePath":"uk/mavlink/adding_messages.md"}'),n={name:"uk/mavlink/adding_messages.md"};function o(r,e,l,d,h,m){return s(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="adding-standard-mavlink-definitions-messages-commands" tabindex="-1">Adding Standard MAVLink Definitions (Messages/Commands) <a class="header-anchor" href="#adding-standard-mavlink-definitions-messages-commands" aria-label="Permalink to &quot;Adding Standard MAVLink Definitions (Messages/Commands)&quot;">​</a></h1><p>This topic explains how to add new MAVLink messages and commands that are expected to be <em>part of</em> the normal PX4 build.</p><h2 id="standard-mavlink-messages" tabindex="-1">Standard MAVLink Messages <a class="header-anchor" href="#standard-mavlink-messages" aria-label="Permalink to &quot;Standard MAVLink Messages&quot;">​</a></h2><p>The PX4/PX4-Autopilot source code uses only messages that have been standardized by MAVLink. That is to say, the standard definitions in <a href="https://mavlink.io/en/messages/common.html" target="_blank" rel="noreferrer">common.xml</a> in releases, and <a href="https://mavlink.io/en/messages/development.html" target="_blank" rel="noreferrer">development.xml</a> during development. These messages are present in at least one significant flight stack, and members of other flight stacks have accepted them as a reasonable design that would likely be adopted if the same functionality was required.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A <a href="./../mavlink/custom_messages">Custom MAVLink Message</a> is one that isn&#39;t part of the standard. These are defined in your own XML as part of your own fork of PX4. If you use <a href="./../mavlink/custom_messages">custom MAVLink messages</a> you will need maintain the definitions in PX4, your ground station, and any other SDKs that communicate with it. Загалом, щоб зменшити тягар обслуговування, слід використовувати (або доповнювати) стандартні визначення, якщо це можливо.</p></div><p>New standard definitions are added first to <code>development.xml</code>, and then moved to <code>common.xml</code> following review and prototyping, and acceptance by the MAVLink team.</p><p>If you intend your message to become part of the default PX4 build you will need to propose it to the MAVLink community by submitting a pull request (PR) to <a href="https://github.com/mavlink/mavlink/blob/master/message_definitions/v1.0/development.xml" target="_blank" rel="noreferrer">development.xml</a>. The <a href="https://mavlink.io/en/getting_started/" target="_blank" rel="noreferrer">MAVLink Developer guide</a> explains how to define new messages in <a href="https://mavlink.io/en/guide/define_xml_element.html" target="_blank" rel="noreferrer">How to Define MAVLink Messages &amp; Enums</a>.</p><h2 id="generating-message-headers" tabindex="-1">Generating Message Headers <a class="header-anchor" href="#generating-message-headers" aria-label="Permalink to &quot;Generating Message Headers&quot;">​</a></h2><p>During development you can add your definitions to <code>PX4-Autopilot/src/modules/mavlink/mavlink/message_definitions/v1.0/development.xml</code> (or pull them from MAVLink).</p><p>When you build PX4, header files for these message definitions are generated in the build directory (<code>/build/&lt;build target&gt;/mavlink/</code>). If headers are not build for your messages, they may be incorrectly formatted, or use clashing ids. Перевірте журнал збірки для отримання інформації.</p><h2 id="implementing-message-senders-receivers" tabindex="-1">Implementing Message Senders/Receivers <a class="header-anchor" href="#implementing-message-senders-receivers" aria-label="Permalink to &quot;Implementing Message Senders/Receivers&quot;">​</a></h2><p>Once the message headers for your definitions are generated in the PX4 build, you can use them in your code to send and receive the messages:</p><ul><li><a href="./../mavlink/streaming_messages">Streaming MAVLink Messages</a></li><li><a href="./../mavlink/receiving_messages">Receiving MAVLink Messages</a></li></ul><h2 id="тестування" tabindex="-1">Тестування <a class="header-anchor" href="#тестування" aria-label="Permalink to &quot;Тестування&quot;">​</a></h2><p>The first step in debugging is to confirm that any messages you&#39;ve created are being sent/received as you expect.</p><p>You should first use the <code>uorb top [&lt;message_name&gt;]</code> command to verify in real-time that your message is published and the rate (see <a href="./../middleware/uorb#uorb-top-command">uORB Messaging</a>). This approach can also be used to test incoming messages that publish a uORB topic (for other messages you might use <code>printf</code> in your code and test in SITL).</p><p>Існує кілька підходів для перегляду трафіку MAVLink:</p><ul><li><p>Create a <a href="https://mavlink.io/en/guide/wireshark.html" target="_blank" rel="noreferrer">Wireshark MAVLink plugin</a> for your dialect. This allows you to inspect MAVLink traffic on an IP interface - for example between <em>QGroundControl</em> or MAVSDK and your real or simulated version of PX4.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>It is much easier to generate a wireshark plugin and inspect traffic in Wireshark, than to rebuild QGroundControl with your dialect and use MAVLink Inspector.</p></div></li></ul><p>:::</p><ul><li><p><a href="./../dev_log/logging">Log uORB topics</a> associate with your MAVLink message.</p></li><li><p>View received messages in the QGroundControl <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/analyze_view/mavlink_inspector.html" target="_blank" rel="noreferrer">MAVLink Inspector</a>. You will need to <a href="#updating-ground-stations">rebuild QGroundControl with the new message definitions</a>.</p></li></ul><h3 id="встановити-швидкість-передачі-за-допомогою-оболонки" tabindex="-1">Встановити швидкість передачі за допомогою оболонки <a class="header-anchor" href="#встановити-швидкість-передачі-за-допомогою-оболонки" aria-label="Permalink to &quot;Встановити швидкість передачі за допомогою оболонки&quot;">​</a></h3><p>Для тестування іноді корисно збільшити швидкість передачі окремих тем під час виконання (наприклад, для перевірки в QGC). This can be achieved using by calling the <a href="./../modules/modules_communication#mavlink">mavlink</a> module through the <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/analyze_view/mavlink_console.html" target="_blank" rel="noreferrer">QGC MAVLink console</a> (or some other shell):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mavlink</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stream</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">port</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> numbe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mavlink</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">rat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>You can get the port number with <code>mavlink status</code> which will output (amongst others) <code>transport protocol: UDP (&lt;port number&gt;)</code>. Прикладом може бути:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mavlink</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stream</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 14556</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CA_TRAJECTORY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span></span></code></pre></div><h2 id="оновлення-наземних-станціи" tabindex="-1">Оновлення наземних станцій <a class="header-anchor" href="#оновлення-наземних-станціи" aria-label="Permalink to &quot;Оновлення наземних станцій&quot;">​</a></h2><p>Зрештою, ви захочете використовувати ваш новий інтерфейс MAVLink, надавши відповідну наземну станцію або реалізацію MAVSDK.</p><p>Важливо пам&#39;ятати, що MAVLink вимагає, щоб ви використовували версію бібліотеки, яка побудована за тим самим визначенням (XML-файл). Отже, якщо ви створили власне повідомлення у PX4, ви не зможете його використати, доки не зберете QGC або MAVSDK з тим самим визначенням.</p><h3 id="оновлення-qgroundcontrol" tabindex="-1">Оновлення QGroundControl <a class="header-anchor" href="#оновлення-qgroundcontrol" aria-label="Permalink to &quot;Оновлення QGroundControl&quot;">​</a></h3><p>You will need to <a href="https://docs.qgroundcontrol.com/master/en/qgc-dev-guide/getting_started/index.html" target="_blank" rel="noreferrer">Build QGroundControl</a> with your custom messages included.</p><p>QGC fetches MAVLink via CMake using settings defined in <a href="https://github.com/mavlink/qgroundcontrol/blob/master/cmake/CustomOptions.cmake" target="_blank" rel="noreferrer"><code>cmake/CustomOptions.cmake</code></a>. The key variables are <code>QGC_MAVLINK_GIT_REPO</code> (the MAVLink repository to fetch), <code>QGC_MAVLINK_GIT_TAG</code> (a specific commit or tag), and <code>QGC_MAVLINK_DIALECT</code> (the dialect, default: <code>all</code>). To use a custom MAVLink repository or dialect, override these in a <code>CustomOverrides.cmake</code> file in the QGC source root.</p><p>QGC uses the <strong>all</strong> dialect by default, which includes <strong>common.xml</strong>. You can include your messages in either file, or <a href="https://mavlink.io/en/getting_started/generate_libraries.html" target="_blank" rel="noreferrer">generate your own MAVLink Libraries</a>.</p><p>Note that if you use your own <em>custom dialect</em> then it should include <strong>all.xml</strong> (or it may miss all the existing messages), and you will need to set <code>QGC_MAVLINK_DIALECT</code> accordingly in <code>CustomOverrides.cmake</code>.</p><h3 id="оновлення-mavsdk" tabindex="-1">Оновлення MAVSDK <a class="header-anchor" href="#оновлення-mavsdk" aria-label="Permalink to &quot;Оновлення MAVSDK&quot;">​</a></h3><p>See the MAVSDK docs for information about how to work with <a href="https://mavsdk.mavlink.io/main/en/cpp/guide/build.html" target="_blank" rel="noreferrer">MAVLink headers and dialects</a>.</p>',35)])])}const g=a(n,[["render",o]]);export{c as __pageData,g as default};
